class Solution:
    def largestValsFromLabels(self, values, labels, numWanted, useLimit):
        n = len(values)
        best = 0
        for mask in range(1 << n):
            cnt = {}
            total = 0
            size = 0
            ok = True
            for i in range(n):
                if mask >> i & 1:
                    size += 1
                    if size > numWanted:
                        ok = False
                        break
                    cnt[labels[i]] = cnt.get(labels[i], 0) + 1
                    if cnt[labels[i]] > useLimit:
                        ok = False
                        break
                    total += values[i]
            if ok:
                best = max(best, total)
        return best

